/*
 * VaPresets.c
 *
 * The preset banks of the four VA slots: VA1 mono basses, VA2 polyphonic
 * sounds, VA3 mono leads, VA4 noises. A preset sets every sound parameter of
 * a slot (not its volume, pan, output and MIDI channel).
 *
 * Values, per page (see enum VaParam):
 *   OSC    W1 W2 SEMI2 FINE2 PW MIX SYNC OCT
 *            waves 0 saw, 1 square, 2 triangle, 3 sine; SEMI2/FINE2 63 = 0;
 *            PW 0 = square; MIX 0 = osc 1 .. 127 = osc 2; OCT 3 = 0 (0..6 = -3..+3)
 *   MIXER  OSC SUB SUBW SUBO NOISE NTYPE DRIVE SLOP
 *            SUBO 0 = -1 octave, 1 = -2; NTYPE 0 white, 1 pink, 2 brown
 *   FILTER CUT RES TYPE FENV KEY FVEL HPF
 *            TYPE 0 LP24 ladder, 1 LP12, 2 BP12, 3 HP12; FENV 63 = 0 (+-8 octaves);
 *            CUT 20 Hz * 2^(CUT * 10/127)
 *   F.ENV  ATK DEC SUS REL      A.ENV  ATK DEC SUS REL VEL
 *            times 0.5 ms * 2^(v * 15.3/127): 40 = 14 ms, 60 = 74 ms, 80 = 0.4 s,
 *            100 = 2 s, 127 = 20 s
 *   LFO    RATE WAVE PITCH CUT PWM DELAY
 *            WAVE 0 sine, 1 tri, 2 saw, 3 square, 4 S&H; CUT 63 = 0
 *   VOICE  MODE GATE GLIDE UNI SPREAD WIDTH
 *            MODE 0 mono, 1 legato, 2 poly; GATE 16 = one step; UNI 0..6 = 1..7 voices
 *
 * Copyright (C) 2026 Erica Synths
 * SPDX-License-Identifier: GPL-3.0-only
 *
 * This file is part of the LXR firmware. It is licensed under the GNU General
 * Public License version 3, with the additional permission and terms in
 * NOTICE.md. See LICENSE and NOTICE.md in the root of the repository.
 */
